        CharSequenceTranslator translator = new DefaultCharSequenceTranslator();
        translator.translate(TEST_STRING, writer);
    }

    @Test
    public void testTranslate_Null_String() throws Exception {
        Writer writer = new StringWriter();
        CharSequenceTranslator translator = new DefaultCharSequenceTranslator();
        translator.translate(NULL_STRING, writer);
        Assert.assertEquals("", writer.toString());
    }

