        Writer writer = new StringWriter();
        CharSequenceTranslator translator = new DefaultCharSequenceTranslator();
        CharSequenceTranslator customTranslator = new CustomCharSequenceTranslator();
        CharSequenceTranslator combinedTranslator = translator.with(customTranslator);
        combinedTranslator.translate(TEST_STRING, writer);
        Assert.assertEquals(TEST_STRING.toUpperCase(), writer.toString());
