    private class DefaultCharSequenceTranslator extends CharSequenceTranslator{
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            return 0;
        }
    }

    private class CustomCharSequenceTranslator extends CharSequenceTranslator{
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            out.write(Character.toUpperCase(input.charAt(index)));
            return 1;
        }
    }
