public class StringUtilsTest{
@Test
  public void testContainsNone_Null(){
    Assert.assertTrue(StringUtils.containsNone(null, null));
    Assert.assertTrue(StringUtils.containsNone(null, new char[0]));
    Assert.assertTrue(StringUtils.containsNone(new String(), null));
  }

  @Test
  public void testContainsNone_NoMatch(){
    Assert.assertTrue(StringUtils.containsNone("hello", new char[]{'a','b','c'}));
    Assert.assertTrue(StringUtils.containsNone("hello", new char[]{'x','y','z'}));
  }

  @Test
  public void testContainsNone_Match(){
    Assert.assertFalse(StringUtils.containsNone("hello", new char[]{'h','e','l','o'}));
    Assert.assertFalse(StringUtils.containsNone("hello", new char[]{'l'}));
  }

  @Test
  public void testContainsNone_HighSurrogate(){
    StringBuilder sb = new StringBuilder();
    sb.append((char) 0xD800);
    sb.append((char) 0xDC00);
    Assert.assertFalse(StringUtils.containsNone(sb.toString(), new char[]{(char) 0xD800}));
    Assert.assertFalse(StringUtils.containsNone(sb.toString(), new char[]{(char) 0xDC00}));
    Assert.assertFalse(StringUtils.containsNone(sb.toString(), new char[]{(char) 0xD800, (char) 0xDC00}));
  }

  @Test
  public void testContainsNone_LowSurrogate_Alone(){
    StringBuilder sb = new StringBuilder();
    sb.append((char) 0xDC00);
    Assert.assertFalse(StringUtils.containsNone(sb.toString(), new char[]{(char) 0xD800}));
  }
}
