    public void toClass_NullArray_ReturnsNull() {
        // Arrange
        Object[] array = null;

        // Act
        Class<?>[] result = ClassUtils.toClass(array);

        // Assert
        Assert.assertNull(result);
    }

    @Test
    public void toClass_EmptyArray_ReturnsEmptyClassArray() {
        // Arrange
        Object[] array = {};

        // Act
        Class<?>[] result = ClassUtils.toClass(array);

        // Assert
        Assert.assertNotNull(result);
        Assert.assertEquals(0, result.length);
    }

    @Test
    public void toClass_NonEmptyArrayWithNullElements_ReturnsClassesWithNull() {
        // Arrange
        Object[] array = { "hello", null, 123 };

        // Act
        Class<?>[] result = ClassUtils.toClass(array);

        // Assert
        Assert.assertNotNull(result);
        Assert.assertEquals(3, result.length);
        Assert.assertEquals(String.class, result[0]);
        Assert.assertNull(result[1]);
        Assert.assertEquals(Integer.class, result[2]);
    }

    @Test
    public void toClass_NonEmptyArrayWithoutNullElements_ReturnsClasses() {
        // Arrange
        Object[] array = { "hello", 123, true };

        // Act
